from itertools import combinations
from pysat.solvers import Glucose3

vertices = list(range(8))
edges = list(combinations(vertices, 2))
edge_to_idx = {e: i for i, e in enumerate(edges)}
n_edges = len(edges)

fixed_present = [(0, 6), (2, 6)]

solver = Glucose3()

# Variables: x_e for each edge e (1 to n_edges)
# Auxiliary variables: z_{i,j,k} for each pair (i,j) and witness k
# Let's assign indices: edges are 1..n_edges, z variables start from n_edges+1

var_counter = n_edges
z_vars = {}  # (i, j, k) -> variable index

def get_z(i, j, k):
    global var_counter
    key = (min(i,j), max(i,j), k)
    if key not in z_vars:
        var_counter += 1
        z_vars[key] = var_counter
    return z_vars[key]

# Fixed edges
for e in fixed_present:
    solver.add_clause([edge_to_idx[e] + 1])

# Triangle-free: for every triple, at most 2 edges
for i, j, k in combinations(vertices, 3):
    e1 = edge_to_idx[tuple(sorted((i, j)))]
    e2 = edge_to_idx[tuple(sorted((j, k)))]
    e3 = edge_to_idx[tuple(sorted((i, k)))]
    solver.add_clause([-(e1 + 1), -(e2 + 1), -(e3 + 1)])

# Maximality: for each pair (i, j), x_{i,j} OR (exists k: z_{i,j,k})
# and z_{i,j,k} => x_{i,k} AND x_{j,k}
for i, j in edges:
    # x_{i,j} OR (OR over k of z_{i,j,k})
    clause = [edge_to_idx[(i, j)] + 1]
    for k in vertices:
        if k != i and k != j:
            z = get_z(i, j, k)
            clause.append(z)
            # z_{i,j,k} => x_{i,k}
            e_ik = edge_to_idx[tuple(sorted((i, k)))]
            solver.add_clause([-z, e_ik + 1])
            # z_{i,j,k} => x_{j,k}
            e_jk = edge_to_idx[tuple(sorted((j, k)))]
            solver.add_clause([-z, e_jk + 1])
    solver.add_clause(clause)

print(f"Total variables: {var_counter}")
print(f"Number of clauses added")

if solver.solve():
    model = solver.get_model()
    edge_set = set()
    for e_idx, e in enumerate(edges):
        if model[e_idx] > 0:
            edge_set.add(e)

    print(f"Found maximal triangle-free graph with {len(edge_set)} edges")
    print(f"Edges: {sorted(edge_set)}")

    # Verify triangle-free
    def is_triangle_free(es):
        for i, j, k in combinations(vertices, 3):
            if (i, j) in es and (j, k) in es and (i, k) in es:
                return False
        return True

    def is_maximal(es):
        for i, j in edges:
            if (i, j) not in es:
                has_witness = False
                for k in vertices:
                    if k != i and k != j:
                        if (i, k) in es and (j, k) in es:
                            has_witness = True
                            break
                if not has_witness:
                    return False
        return True

    print(f"Triangle-free: {is_triangle_free(edge_set)}")
    print(f"Maximal: {is_maximal(edge_set)}")
else:
    print("UNSATISFIABLE")

from itertools import combinations

vertices = list(range(8))
edges = list(combinations(vertices, 2))

edge_set = {(0, 1), (0, 3), (0, 4), (0, 5), (0, 6), (1, 2), (1, 7), (2, 3), (2, 4), (2, 5), (2, 6), (3, 7), (4, 7), (5, 7), (6, 7)}

def is_triangle_free(es):
    for i, j, k in combinations(vertices, 3):
        e1 = tuple(sorted((i, j)))
        e2 = tuple(sorted((j, k)))
        e3 = tuple(sorted((i, k)))
        if e1 in es and e2 in es and e3 in es:
            return False
    return True

def is_maximal(es):
    for i, j in edges:
        if (i, j) not in es:
            has_witness = False
            for k in vertices:
                if k != i and k != j:
                    e1 = tuple(sorted((i, k)))
                    e2 = tuple(sorted((j, k)))
                    if e1 in es and e2 in es:
                        has_witness = True
                        break
            if not has_witness:
                print(f"Non-edge ({i}, {j}) has no witness")
                return False
    return True

print(f"Triangle-free: {is_triangle_free(edge_set)}")
print(f"Maximal: {is_maximal(edge_set)}")

# Also verify fixed edges
print(f"Fixed (0,6) present: {(0,6) in edge_set}")
print(f"Fixed (2,6) present: {(2,6) in edge_set}")
